(function(){
const {R,pick,shuffle,sample,range,plural,gcd}=H;
const M=s=>`<span class="m">${s}</span>`;
const n=x=>H.num(x);
const sq=x=>H.sqrt(x);
const fr=(a,b)=>H.frac(a,b);
const P=x=>x<0?`(${n(x)})`:n(x);
const isSq=v=>v>=0&&Math.round(Math.sqrt(v))**2===v;
function poly(ts){let s='';ts.forEach(([c,v])=>{if(!c)return;const neg=c<0,a=Math.abs(c);const body=v?(a===1?'':n(a))+v:n(a);s+=s?(neg?' − ':' + ')+body:(neg?'−':'')+body;});return s||'0';}
const Q=(a,b,c,v)=>{v=v||'x';return poly([[a,v+'²'],[b,v],[c,'']]);};
function rat(p,q){if(q<0){p=-p;q=-q;}const g=gcd(p,q)||1;p/=g;q/=g;return q===1?n(p):(p<0?'−':'')+fr(Math.abs(p),q);}
function mk(correct,traps){const o=[correct];traps.forEach(t=>{if(t&&!o.includes(t))o.push(t);});const s=shuffle(o);return {opts:s,ans:s.indexOf(correct)};}
const nz=(a,b)=>{let v;do{v=R(a,b);}while(!v);return v;};
const setTxt=arr=>arr.length?'{'+arr.join(', ')+'}':'∅';
const SETKEYS=['∅','−','/'];
const SETPH='корни через запятую (дробь — как 3/2), нет корней — ∅';
const sgn=v=>v<0?'−':'+';
/* приведённое уравнение с D > 0 (не обязательно с целыми корнями) */
function redEq(nonSq){let p,q;do{p=nz(-9,9);q=nz(-12,12);}while(p*p-4*q<=0||(nonSq&&isSq(p*p-4*q)));return [p,q];}
const vs=(p,q)=>`x₁ + x₂ = −p = ${n(-p)}, &nbsp;x₁·x₂ = q = ${n(q)}`;

/* ---------- парабола ---------- */
function plot(a,b,c,o){o=o||{};const W=320,Hh=230,X0=160,Y0=o.y0||125,s=18;
  let g=`<svg viewBox="0 0 ${W} ${Hh}" width="${W}" role="img" aria-label="График" style="font-family:system-ui,sans-serif">`;
  for(let i=-8;i<=8;i++){const x=X0+i*s;g+=`<line x1="${x}" y1="0" x2="${x}" y2="${Hh}" stroke="var(--line)" stroke-width="1"/>`;}
  for(let j=-8;j<=8;j++){const y=Y0-j*s;if(y<0||y>Hh)continue;g+=`<line x1="0" y1="${y}" x2="${W}" y2="${y}" stroke="var(--line)" stroke-width="1"/>`;}
  g+=`<line x1="0" y1="${Y0}" x2="${W}" y2="${Y0}" stroke="var(--fig)" stroke-width="1.4"/><line x1="${X0}" y1="0" x2="${X0}" y2="${Hh}" stroke="var(--fig)" stroke-width="1.4"/>`;
  g+=`<text x="${W-8}" y="${Y0-6}" font-size="13" fill="var(--ink)" text-anchor="end">x</text><text x="${X0+7}" y="13" font-size="13" fill="var(--ink)">y</text>`;
  [-6,-4,-2,2,4,6].forEach(t=>{g+=`<text x="${X0+t*s}" y="${Y0+14}" font-size="10" fill="var(--muted)" text-anchor="middle">${n(t)}</text>`;});
  let d='';for(let x=-9.2;x<=9.2;x+=0.05){let y=a*x*x+b*x+c;let py=Y0-y*s;py=Math.max(-60,Math.min(Hh+60,py));d+=(d?'L':'M')+(X0+x*s).toFixed(1)+','+py.toFixed(1);}
  g+=`<path d="${d}" fill="none" stroke="var(--accent)" stroke-width="2.6"/>`;
  (o.roots||[]).forEach(r=>{g+=`<circle cx="${X0+r*s}" cy="${Y0}" r="5" fill="var(--hl)" stroke="var(--card)" stroke-width="1.5"/>`;});
  return g+'</svg>';}

/* ---------- theory ---------- */
const theory=[
{title:'Теорема Виета',lvl:0,html:`
<p class="hook">🕵️ Конец XVI века, Франция воюет с Испанией. Французы перехватывают испанские письма, зашифрованные кодом из сотен знаков. Король Генрих IV отдаёт их своему советнику — юристу <b>Франсуа Виету</b>. Виет взламывает шифр. Испанский король Филипп II в ярости жалуется римскому папе: французы, мол, используют <b>чёрную магию</b>! А «магия» Виета была в том, что он умел замечать закономерности. Одну из них ты сейчас узнаешь — и будешь находить корни уравнений в уме, без дискриминанта.</p>
<div class="box rule"><b>Теорема Виета (для приведённого уравнения)</b>Если x₁ и x₂ — корни уравнения ${M('x² + px + q = 0')}, то<br>${M('x₁ + x₂ = −p')}, &nbsp;&nbsp;${M('x₁ · x₂ = q')}.<br>Сумма корней — второй коэффициент с <b>противоположным знаком</b>, произведение — свободный член.</div>
<p><b>Почему работает?</b> Если x₁, x₂ — корни, то трёхчлен раскладывается: ${M('x² + px + q = (x − x₁)(x − x₂)')}. Раскроем скобки: ${M('(x − x₁)(x − x₂) = x² − (x₁ + x₂)x + x₁x₂')}. Сравниваем коэффициенты: ${M('p = −(x₁ + x₂)')}, ${M('q = x₁x₂')}. Вот и вся магия!</p>
<div class="box ex"><b>Пример</b>${M('x² − 7x + 10 = 0')}: x₁ + x₂ = 7, x₁·x₂ = 10. Какие числа? 2 и 5! Проверь: 2 + 5 = 7, 2·5 = 10.</div>
<div class="box err"><b>Главная ловушка</b>Теорема говорит о корнях, <b>если они есть</b>. У ${M('x² + 2x + 10 = 0')} D = 4 − 40 < 0 — корней нет, и «сумма корней = −2» — бессмыслица. Всегда помни про D ≥ 0!</div>
<div class="box err"><b>Ловушка со знаком</b>Сумма = <b>−p</b>. В ${M('x² + 5x + 6 = 0')} сумма корней −5, а не 5 (корни −2 и −3).</div>
<div class="fact">Виет первым стал систематически обозначать буквами не только неизвестные, но и <b>данные</b> числа: неизвестные — гласными, известные — согласными. Именно благодаря ему мы пишем «ax² + bx + c» вместо длинных словесных рецептов.</div>`},
{title:'Теорема Виета для любого квадратного уравнения',lvl:1,html:`
<div class="box rule"><b>Общий вид</b>Если x₁, x₂ — корни ${M('ax² + bx + c = 0')}, то ${M(`x₁ + x₂ = ${fr('−b','a')}`)}, &nbsp;${M(`x₁ · x₂ = ${fr('c','a')}`)}.</div>
<p><b>Почему?</b> Разделим уравнение на a — получим приведённое: ${M(`x² + ${fr('b','a')}x + ${fr('c','a')} = 0`)}. Тут p = b/a, q = c/a — и работает обычная теорема.</p>
<div class="box ex"><b>Пример</b>${M('3x² − 6x − 9 = 0')}: x₁ + x₂ = ${fr('6','3')} = 2, x₁x₂ = ${fr('−9','3')} = −3. (Корни 3 и −1.)</div>
<div class="box ex"><b>Пример с минусом впереди</b>${M('−2x² + 8x + 10 = 0')}: x₁ + x₂ = ${fr('−8','−2')} = 4, x₁x₂ = ${fr('10','−2')} = −5.</div>
<div class="box err"><b>Частая ошибка</b>Забыть поделить на a: «сумма = −b». Это верно только при a = 1.</div>
<div class="fact">В школе есть стишок, который помнят даже взрослые: «По праву достойна в стихах быть воспета / О свойствах корней теорема Виета…»</div>`},
{title:'Корни в уме: подбор',lvl:2,html:`
<div class="box rule"><b>Как подобрать корни ${M('x² + px + q = 0')}</b>Ищем два числа, у которых <b>произведение q</b> и <b>сумма −p</b>.</div>
<ol class="steps"><li>Начни с произведения: выпиши пары множителей числа q.</li><li>Знаки: если q > 0 — корни одного знака (знак как у −p); если q < 0 — разных.</li><li>Из пар выбери ту, у которой нужная сумма.</li></ol>
<div class="box ex"><b>Пример</b>${M('x² + x − 12 = 0')}: произведение −12, сумма −1.<br>Пары для 12: 1·12, 2·6, 3·4. Разные знаки, сумма −1 → <b>3 и −4</b>.</div>
<div class="box ex"><b>Пример с a ≠ 1</b>${M('2x² − 14x + 24 = 0')}: делим на 2 → ${M('x² − 7x + 12 = 0')} → 3 и 4.</div>
<div class="box tip"><b>Супертрюк</b>Если a + b + c = 0, то корни <b>1</b> и <b>c/a</b>. Если a − b + c = 0, то <b>−1</b> и <b>−c/a</b>. Почему: один корень 1 (или −1) видно подстановкой, а второй — из произведения x₁x₂ = c/a.<br>${M('7x² − 9x + 2 = 0')}: 7 − 9 + 2 = 0 → корни 1 и ${fr(2,7)}.</div>
<div class="box err"><b>Ловушка</b>Подбор — для «красивых» уравнений. Если за минуту не нашёл — считай D. Корни могут быть дробными или с корнями.</div>`},
{title:'Обратная теорема: уравнение по корням',lvl:3,html:`
<div class="box rule"><b>Обратная теорема Виета</b>Если числа m и n таковы, что ${M('m + n = −p')} и ${M('m · n = q')}, то m и n — корни уравнения ${M('x² + px + q = 0')}.</div>
<p>Значит, уравнение с корнями x₁, x₂ можно сразу записать: ${M('x² − (x₁ + x₂)x + x₁x₂ = 0')}.</p>
<div class="box ex"><b>Пример</b>Корни 3 и −5: сумма −2, произведение −15 → ${M('x² + 2x − 15 = 0')}.</div>
<div class="box ex"><b>Пример с дробью</b>Корни ${fr(1,2)} и 3: сумма ${fr(7,2)}, произведение ${fr(3,2)} → ${M(`x² − ${fr(7,2)}x + ${fr(3,2)} = 0`)}. Умножим на 2: ${M('2x² − 7x + 3 = 0')}.</div>
<div class="box ex"><b>Пример с корнями</b>Корни ${M('2 ± √3')}: сумма 4 (корни сократились), произведение 4 − 3 = 1 → ${M('x² − 4x + 1 = 0')}.</div>
<div class="box err"><b>Ловушка со знаком</b>В уравнении стоит <b>минус</b> сумма: корни 3 и 4 → ${M('x² − 7x + 12')}, а не ${M('x² + 7x + 12')}.</div>
<p><b>Поиграй:</b> задай корни ползунками — увидишь уравнение и параболу, которая проходит через эти точки.</p>
<div class="widget" id="w-vieta"></div>`},
{title:'Симметрические выражения без решения',lvl:[4,5],html:`
<p>Хитрость олимпиадников: многие выражения от корней можно найти, <b>не находя самих корней</b>. Нужно выразить их через сумму s = x₁ + x₂ и произведение t = x₁x₂.</p>
<div class="box rule"><b>Формулы</b>
${M('x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = s² − 2t')}<br>
${M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr('x₁ + x₂','x₁x₂')} = ${fr('s','t')}`)}<br>
${M(`${fr('x₁','x₂')} + ${fr('x₂','x₁')} = ${fr('x₁² + x₂²','x₁x₂')} = ${fr('s² − 2t','t')}`)}<br>
${M('(x₁ − x₂)² = s² − 4t')} &nbsp;(отсюда ${M('|x₁ − x₂| = √(s² − 4t)')})<br>
${M('x₁³ + x₂³ = s³ − 3ts')}<br>
${M('x₁²x₂ + x₁x₂² = x₁x₂(x₁ + x₂) = ts')}</div>
<p><b>Откуда первая?</b> ${M('(x₁ + x₂)² = x₁² + 2x₁x₂ + x₂²')} — лишнее 2x₁x₂ вычитаем. Кубы: ${M('(x₁ + x₂)³ = x₁³ + x₂³ + 3x₁x₂(x₁ + x₂)')}.</p>
<div class="box ex"><b>Пример</b>${M('x² − 3x − 1 = 0')} (корни некрасивые!): s = 3, t = −1.<br>x₁² + x₂² = 9 + 2 = 11. &nbsp;1/x₁ + 1/x₂ = 3/(−1) = −3. &nbsp;x₁³ + x₂³ = 27 + 9 = 36.</div>
<div class="box err"><b>Ловушка-сюрприз</b>${M('x² + 2x + 5 = 0')}: «x₁² + x₂² = 4 − 10 = −6». Сумма квадратов — отрицательная?! Это сигнал: корней нет (D = −16). Перед вычислениями проверь D ≥ 0.</div>`},
{title:'Знаки корней — не решая',lvl:6,html:`
<div class="box rule"><b>Правило (x² + px + q = 0, D > 0)</b>
<b>q < 0</b> → корни разных знаков (и D проверять не нужно — он точно > 0).<br>
<b>q > 0, p < 0</b> → оба корня положительные.<br>
<b>q > 0, p > 0</b> → оба корня отрицательные.</div>
<p><b>Почему?</b> Произведение q < 0 — множители разных знаков. Произведение q > 0 — одного знака, а какого — подскажет сумма −p.</p>
<p>А при q < 0 больший по модулю корень имеет знак суммы −p.</p>
<div class="box ex"><b>Пример</b>${M('x² − 2x − 15 = 0')}: q = −15 < 0 → разных знаков; сумма 2 > 0 → положительный корень больше по модулю (это 5 и −3).</div>
<div class="box err"><b>Ловушка</b>${M('x² − 2x + 5 = 0')}: q > 0, p < 0 — «оба положительные»? Нет! D = 4 − 20 < 0 — корней вообще нет. При q > 0 сначала проверь D.</div>`},
{title:'Если один корень известен',lvl:7,html:`
<div class="box rule"><b>Правило</b>Знаешь один корень — второй найдёшь из суммы ${M('x₂ = −p − x₁')} или из произведения ${M('x₂ = q / x₁')}.</div>
<div class="box ex"><b>Пример 1</b>Корень уравнения ${M('x² − 9x + q = 0')} равен 4. Сумма 9 → x₂ = 5. Тогда q = 4·5 = 20.</div>
<div class="box ex"><b>Пример 2</b>Корень уравнения ${M('x² + px − 18 = 0')} равен 3. Произведение −18 → x₂ = −6. p = −(3 − 6) = 3.</div>
<div class="box tip"><b>Совет</b>Бери ту формулу, где неизвестного коэффициента нет: известно p — через сумму, известно q — через произведение.</div>`},
{title:'★ Олимпиадные идеи',lvl:8,html:`
<div class="box rule"><b>Целые корни</b>Если p, q — целые и корни целые, то каждый корень — делитель q (ведь x₁x₂ = q). Перебираем пары делителей — и находим все возможные p = −(x₁ + x₂).</div>
<div class="box ex"><b>Пример</b>При каких целых p корни ${M('x² + px + 6 = 0')} целые? Пары: (1, 6), (2, 3), (−1, −6), (−2, −3) → p = −7, −5, 7, 5. Четыре значения.</div>
<div class="box rule"><b>Условие на корни + проверка D</b>Нашёл параметр через Виета — проверь, что корни существуют (D ≥ 0). Иначе ответ может оказаться «фальшивым».</div>
<div class="box ex"><b>Пример</b>При каких p сумма квадратов корней ${M('x² + px + 5 = 0')} равна 6? p² − 10 = 6 → p = ±4. Но D = 16 − 20 < 0 → корней нет! Ответ: таких p нет.</div>
<div class="box rule"><b>Новое уравнение из старого</b>Уравнение с корнями x₁², x₂²: сумма s² − 2t, произведение t² → ${M('y² − (s² − 2t)y + t² = 0')}.</div>`},
{title:'Шпаргалка',html:`
<ul class="steps"><li>${M('x² + px + q = 0')}: x₁ + x₂ = −p, x₁x₂ = q.</li>
<li>${M('ax² + bx + c = 0')}: x₁ + x₂ = −b/a, x₁x₂ = c/a.</li>
<li>Сначала проверь, что корни есть (D ≥ 0).</li>
<li>По корням: ${M('x² − (x₁ + x₂)x + x₁x₂ = 0')}.</li>
<li>x₁² + x₂² = s² − 2t, 1/x₁ + 1/x₂ = s/t, x₁³ + x₂³ = s³ − 3ts.</li>
<li>q < 0 → разные знаки; q > 0 → один знак, как у −p.</li></ul>`}
];

const symbols={tab:'Формулы',title:'Формулы Виета и их следствия',rows:[
['x₁ + x₂ = −p','Сумма корней (приведённое)','Второй коэффициент с обратным знаком.',M('x² − 7x + 10: сумма 7')],
['x₁ · x₂ = q','Произведение корней','Свободный член.',M('x² − 7x + 10: произведение 10')],
[`x₁ + x₂ = ${fr('−b','a')}`,'Сумма (общий вид)','Делим на старший коэффициент.',M(`3x² − 6x − 9: сумма 2`)],
[`x₁ · x₂ = ${fr('c','a')}`,'Произведение (общий вид)','Тоже делим на a.',M('3x² − 6x − 9: произведение −3')],
['x² − (x₁ + x₂)x + x₁x₂ = 0','Уравнение по корням','Обратная теорема.',M('корни 2 и 5 → x² − 7x + 10 = 0')],
['s² − 2t','x₁² + x₂²','s — сумма, t — произведение.',M('s = 3, t = −1 → 11')],
[fr('s','t'),'1/x₁ + 1/x₂','Общий знаменатель x₁x₂.',M('s = 3, t = −1 → −3')],
['s² − 4t','(x₁ − x₂)²','Это дискриминант приведённого уравнения.',M('s = 7, t = 10 → 9, |x₁ − x₂| = 3')],
['s³ − 3ts','x₁³ + x₂³','Из куба суммы.',M('s = 3, t = −1 → 36')]
],after:`<div class="box tip" style="margin-top:14px"><b>Самое важное</b>Знак суммы — противоположный коэффициенту при x. И не забывай проверять, что корни вообще есть.</div>`};

/* ---------- generators ---------- */
const gens=[];
const G=(lvl,make,f)=>gens.push({lvl,make,star:f==='s'||undefined,rule:f==='r'||undefined});

/* L0 */
G(0,()=>{const o=mk(M('x₁ + x₂ = −p, &nbsp;x₁ · x₂ = q'),[M('x₁ + x₂ = p, &nbsp;x₁ · x₂ = q'),M('x₁ + x₂ = −p, &nbsp;x₁ · x₂ = −q'),M('x₁ + x₂ = q, &nbsp;x₁ · x₂ = −p')]);
return {type:'choice',q:`Допиши теорему Виета: если x₁, x₂ — корни ${M('x² + px + q = 0')}, то…`,...o,short:'Сумма = −p, произведение = q.',
explain:`Теорема Виета: ${M('x₁ + x₂ = −p')}, ${M('x₁x₂ = q')}.<br>Откуда: ${M('(x − x₁)(x − x₂) = x² − (x₁ + x₂)x + x₁x₂')}. Сравни с ${M('x² + px + q')}: p = −(x₁ + x₂), q = x₁x₂.<br>Минус — только у суммы.`,
explain2:`Проверь на уравнении с известными корнями: ${M('x² − 5x + 6 = 0')}, корни 2 и 3. Сумма 5 = −(−5) = −p ✅, произведение 6 = q ✅. Вариант «сумма = p» дал бы −5 ✗.`};},'r');
G(0,()=>{const ok=`для приведённого уравнения ${M('x² + px + q = 0')}, у которого есть корни (D ≥ 0)`;
const o=mk(ok,[`для любого уравнения ${M('ax² + bx + c = 0')} — сумма всегда −b`,'только когда p и q положительные','только когда корни целые']);
return {type:'choice',q:`Когда можно пользоваться формулами ${M('x₁ + x₂ = −p')}, ${M('x₁x₂ = q')}?`,...o,short:'Приведённое уравнение (a = 1) и корни существуют.',
explain:`Формулы в таком виде — для <b>приведённого</b> уравнения (a = 1). Для ${M('ax² + bx + c = 0')} нужно делить на a: сумма −b/a, произведение c/a.<br>И главное — корни должны <b>существовать</b> (D ≥ 0). Знаки p и q и целость корней не важны: для ${M('x² − 3x − 1 = 0')} корни некрасивые, но их сумма всё равно 3.`,
explain2:`Контрпримеры: ${M('2x² − 6x + 4 = 0')} — корни 1 и 2, сумма 3, а не 6 (a ≠ 1). ${M('x² + x + 1 = 0')} — D < 0, корней нет, говорить о сумме нельзя.`};},'r');
G(0,()=>{const [p,q]=redEq(true);
return {type:'num',q:`Не решая уравнение ${M(Q(1,p,q)+' = 0')}, найди <b>сумму</b> его корней.`,ans:-p,hint:'Сначала убедись, что корни есть (D > 0). Потом — теорема Виета.',
short:`D = ${p*p-4*q} > 0, x₁ + x₂ = −p = ${n(-p)}.`,
explain:`1) Корни есть: D = ${P(p)}² − 4·${P(q)} = ${p*p-4*q} > 0.<br>2) По теореме Виета ${M('x₁ + x₂ = −p')}. Здесь p = ${n(p)}, значит сумма = <b>${n(-p)}</b>.<br>Ошибка «${n(p)}» — забыли сменить знак.`,
explain2:`Корни тут некрасивые: x = ${fr(`${n(-p)} ± ${sq(p*p-4*q)}`,2)}. Сложим их: корни с «+√» и «−√» сократятся, останется ${fr(`${n(-p)} + ${P(-p)}`,2)} = ${n(-p)}. Теорема Виета дала это без всяких корней!`};});
G(0,()=>{const [p,q]=redEq(true);
return {type:'num',q:`Не решая уравнение ${M(Q(1,p,q)+' = 0')}, найди <b>произведение</b> его корней.`,ans:q,hint:'Произведение корней приведённого уравнения — это свободный член.',
short:`D = ${p*p-4*q} > 0, x₁x₂ = q = ${n(q)}.`,
explain:`1) D = ${P(p)}² − 4·${P(q)} = ${p*p-4*q} > 0 — корни есть.<br>2) ${M('x₁ · x₂ = q')} = <b>${n(q)}</b>. Знак не меняем — меняется только у суммы.`,
explain2:`Почему произведение — это q: ${M(Q(1,p,q))} = (x − x₁)(x − x₂). Подставь x = 0: слева ${n(q)}, справа (−x₁)(−x₂) = x₁x₂. Значит x₁x₂ = ${n(q)}.`};});
G(0,()=>{const neg=Math.random()<0.5;let p,q;do{p=nz(-8,8);q=nz(-8,15);}while(neg?(p*p-4*q>=0):(p*p-4*q<=0));const D=p*p-4*q;
const none='у уравнения нет корней — сумму найти нельзя';const o=mk(neg?none:n(-p),[none,n(-p),n(p),n(q)]);
return {type:'choice',q:`Чему равна сумма корней уравнения ${M(Q(1,p,q)+' = 0')}?`,...o,hint:'Не спеши с теоремой Виета — сначала проверь, есть ли корни.',
short:neg?`D = ${D} < 0 — корней нет.`:`D = ${D} > 0, сумма = −p = ${n(-p)}.`,
explain:`Сначала дискриминант: D = ${P(p)}² − 4·${P(q)} = ${D}.<br>${neg?`D < 0 → <b>корней нет</b>. Теорема Виета ничего не говорит о несуществующих корнях, поэтому ответ «${n(-p)}» — ловушка.`:`D > 0 → корни есть, и по Виета сумма = −p = <b>${n(-p)}</b>.`}`,
explain2:neg?`Посмотри на график y = ${Q(1,p,q)}: парабола целиком над осью x — точек пересечения (корней) нет.<div class="fig">${plot(1,p,q)}</div>`:`График y = ${Q(1,p,q)} пересекает ось x в двух точках, симметричных относительно вершины x = ${n(-p/2)}. Сумма двух симметричных точек = 2·${P(-p/2)} = ${n(-p)}.`};});

/* L1 */
G(1,()=>{const o=mk(M(`x₁ + x₂ = ${fr('−b','a')}, &nbsp;x₁x₂ = ${fr('c','a')}`),[M(`x₁ + x₂ = ${fr('b','a')}, &nbsp;x₁x₂ = ${fr('c','a')}`),M('x₁ + x₂ = −b, &nbsp;x₁x₂ = c'),M(`x₁ + x₂ = ${fr('−b','a')}, &nbsp;x₁x₂ = ${fr('−c','a')}`)]);
return {type:'choice',q:`Теорема Виета для уравнения ${M('ax² + bx + c = 0')} (a ≠ 0):`,...o,short:'Делим на a: сумма −b/a, произведение c/a.',
explain:`Разделим на a: ${M(`x² + ${fr('b','a')}x + ${fr('c','a')} = 0`)} — приведённое, p = b/a, q = c/a.<br>Значит, ${M(`x₁ + x₂ = −${fr('b','a')}`)}, ${M(`x₁x₂ = ${fr('c','a')}`)}.<br>«−b и c» без деления — верно только при a = 1.`,
explain2:`Пример: ${M('2x² − 6x + 4 = 0')}, корни 1 и 2. Сумма 3 = −(−6)/2 ✅, произведение 2 = 4/2 ✅. Без деления получилось бы 6 и 4 ✗.`};},'r');
G(1,()=>{let a,b,c;do{a=pick([-3,-2,2,3,4,5]);b=a*nz(-6,6);c=nz(-15,15);}while(b*b-4*a*c<=0);
return {type:'num',q:`Не решая уравнение ${M(Q(a,b,c)+' = 0')}, найди сумму его корней.`,ans:-b/a,hint:'x₁ + x₂ = −b/a. Следи за знаком a.',
short:`x₁ + x₂ = −b/a = ${fr(n(-b),n(a))} = ${n(-b/a)}.`,
explain:`D = ${b*b} − 4·${P(a)}·${P(c)} = ${b*b-4*a*c} > 0 — корни есть.<br>${M(`x₁ + x₂ = ${fr('−b','a')}`)} = ${fr(n(-b),n(a))} = <b>${n(-b/a)}</b>.${a<0?'<br>Внимание: a отрицательный, поэтому знак ещё раз меняется!':''}`,
explain2:`Раздели уравнение на ${n(a)}: коэффициент при x станет ${n(b)} : ${P(a)} = ${n(b/a)}. В приведённом уравнении сумма корней — коэффициент при x с обратным знаком: ${n(-b/a)}.`};});
G(1,()=>{let a,b,c;do{a=pick([-4,-3,-2,2,3,4,5]);b=nz(-12,12);c=a*nz(-6,6);}while(b*b-4*a*c<=0);
return {type:'num',q:`Не решая уравнение ${M(Q(a,b,c)+' = 0')}, найди произведение его корней.`,ans:c/a,hint:'x₁x₂ = c/a.',
short:`x₁x₂ = c/a = ${fr(n(c),n(a))} = ${n(c/a)}.`,
explain:`D = ${b*b} − 4·${P(a)}·${P(c)} = ${b*b-4*a*c} > 0 — корни есть.<br>${M(`x₁x₂ = ${fr('c','a')}`)} = ${fr(n(c),n(a))} = <b>${n(c/a)}</b>.<br>Ошибка «${n(c)}» — забыли поделить на a = ${n(a)}.`,
explain2:`Раздели всё уравнение на ${n(a)}: свободный член станет ${n(c)}/${P(a)} = ${n(c/a)}. В приведённом уравнении произведение корней — это свободный член.`};});
G(1,()=>{let a,b,c;do{a=pick([2,3,4,5,-2,-3]);b=nz(-15,15);c=nz(-15,15);}while(b*b-4*a*c<=0);
const f=(s,t)=>`x₁ + x₂ = ${s}, &nbsp;x₁x₂ = ${t}`;const ok=f(rat(-b,a),rat(c,a));
const o=mk(ok,[f(n(-b),n(c)),f(rat(b,a),rat(c,a)),f(rat(-b,a),rat(-c,a))]);
return {type:'choice',q:`Найди сумму и произведение корней уравнения ${M(Q(a,b,c)+' = 0')}.`,...o,short:`−b/a = ${rat(-b,a)}, c/a = ${rat(c,a)}.`,
explain:`a = ${n(a)}, b = ${n(b)}, c = ${n(c)}. D = ${b*b-4*a*c} > 0.<br>Сумма: ${fr('−b','a')} = ${fr(n(-b),n(a))} = <b>${rat(-b,a)}</b>.<br>Произведение: ${fr('c','a')} = ${fr(n(c),n(a))} = <b>${rat(c,a)}</b>.<br>Типичные ошибки: не делить на a; поставить «минус» у произведения или потерять его у суммы.`,
explain2:`Сделай уравнение приведённым: раздели на ${n(a)} → ${M(`x² ${sgn(b/a)} ${Math.abs(b)===Math.abs(a)?'':rat(Math.abs(b),Math.abs(a))}x ${sgn(c/a)} ${rat(Math.abs(c),Math.abs(a))} = 0`)}. Теперь p = ${rat(b,a)}, q = ${rat(c,a)}: сумма −p = ${rat(-b,a)}, произведение q = ${rat(c,a)}.`};});

/* L2 */
G(2,()=>{const o=mk('найти два числа, у которых произведение равно q, а сумма равна −p',['найти два числа, у которых произведение равно q, а сумма равна p','найти два числа, у которых сумма равна q, а произведение равно −p','найти два числа, у которых произведение равно −q, а сумма равна −p']);
return {type:'choice',q:`Как подобрать корни уравнения ${M('x² + px + q = 0')} в уме?`,...o,short:'Произведение q, сумма −p.',
explain:`По теореме Виета x₁x₂ = q и x₁ + x₂ = −p. Поэтому ищем два числа: <b>произведение q, сумма −p</b>.<br>Пример: ${M('x² − 8x + 15 = 0')}: произведение 15, сумма 8 → 3 и 5.`,
explain2:`Начинай с произведения: множителей у числа немного. Например, для q = 15: 1·15, 3·5. Потом проверь сумму. С суммой p (без минуса) получились бы числа с неправильными знаками.`};},'r');
G(2,()=>{let r1,r2;do{r1=nz(-9,9);r2=nz(-9,9);}while(r1===r2||r1*r2>0||r1===-r2);const p=-(r1+r2),q=r1*r2;
return {type:'set',q:`Подбери корни уравнения ${M(Q(1,p,q)+' = 0')} по теореме Виета.`,ans:[r1,r2],keys:SETKEYS,ph:SETPH,hint:`Произведение ${n(q)} < 0 → корни разных знаков. Сумма ${n(-p)}.`,
short:`${n(r1)}·${P(r2)} = ${n(q)}, ${n(r1)} + ${P(r2)} = ${n(-p)}.`,
explain:`Нужны числа: произведение <b>${n(q)}</b>, сумма <b>${n(-p)}</b>.<br>Произведение отрицательно → знаки разные. Пары множителей ${Math.abs(q)}: ${range(1,Math.abs(q)).filter(d=>Math.abs(q)%d===0&&d*d<=Math.abs(q)).map(d=>`${d}·${Math.abs(q)/d}`).join(', ')}.<br>Разность по модулю должна быть ${Math.abs(p)}, а больший по модулю — со знаком ${-p>0?'«+»':'«−»'}: это <b>${n(r1)} и ${n(r2)}</b>.`,
explain2:`Проверим: ${n(r1)} + ${P(r2)} = ${n(r1+r2)} = −p ✅, ${n(r1)}·${P(r2)} = ${n(q)} = q ✅. Если не получается подобрать — всегда есть D: ${p*p-4*q}, √D = ${Math.abs(r1-r2)}.`};});
G(2,()=>{const sign=pick([1,-1]);let r1,r2;do{r1=sign*R(1,9);r2=sign*R(1,9);}while(r1===r2);const p=-(r1+r2),q=r1*r2;
return {type:'set',q:`Реши уравнение ${M(Q(1,p,q)+' = 0')} подбором.`,ans:[r1,r2],keys:SETKEYS,ph:SETPH,hint:`Произведение ${q} > 0 → одного знака. Какого — подскажет сумма ${n(-p)}.`,
short:`Сумма ${n(-p)}, произведение ${q} → ${n(r1)} и ${n(r2)}.`,
explain:`Произведение ${q} > 0 → корни одного знака; сумма ${n(-p)} ${sign>0?'> 0 → оба положительные':'< 0 → оба отрицательные'}.<br>Пары множителей ${q}: ${range(1,q).filter(d=>q%d===0&&d*d<=q).map(d=>`${d}·${q/d}`).join(', ')}. Сумма ${Math.abs(p)} — у пары ${Math.abs(r1)} и ${Math.abs(r2)}.<br>Ответ: <b>{${n(Math.min(r1,r2))}, ${n(Math.max(r1,r2))}}</b>.`,
explain2:`Частая ошибка — взять знаки как у p: корни ${n(-r1)} и ${n(-r2)}. Проверь: их сумма ${n(-r1-r2)} ≠ ${n(-p)}. Сумма корней — это −p, а не p.`};});
G(2,()=>{let k,r1,r2;do{k=pick([2,3,4,5,-2,-3]);r1=nz(-8,8);r2=nz(-8,8);}while(r1===r2);const a=k,b=-k*(r1+r2),c=k*r1*r2;
return {type:'set',q:`Реши уравнение ${M(Q(a,b,c)+' = 0')}, подобрав корни.`,ans:[r1,r2],keys:SETKEYS,ph:SETPH,hint:`Все коэффициенты делятся на ${n(k)}. Раздели — станет приведённым.`,
short:`÷${P(k)}: ${M(Q(1,-(r1+r2),r1*r2)+' = 0')} → ${n(r1)}, ${n(r2)}.`,
explain:`Делим обе части на ${n(k)}: ${M(Q(1,-(r1+r2),r1*r2)+' = 0')}.<br>Произведение ${n(r1*r2)}, сумма ${n(r1+r2)} → корни <b>${n(r1)} и ${n(r2)}</b>.<br>Деление на число ≠ 0 корни не меняет.`,
explain2:`Можно и без деления, по общей формуле Виета: сумма −b/a = ${fr(n(-b),n(a))} = ${n(r1+r2)}, произведение c/a = ${fr(n(c),n(a))} = ${n(r1*r2)}. Те же числа.`};});
G(2,()=>{let a,c;do{a=R(2,9);c=nz(-9,9);}while(Math.abs(c)===a);const plus=Math.random()<0.5;const b=plus?-(a+c):a+c;const r=[plus?1:-1,plus?c/a:-c/a];
return {type:'set',q:`Реши уравнение ${M(Q(a,b,c)+' = 0')} без дискриминанта.`,ans:r,ansText:setTxt([n(r[0]),rat(plus?c:-c,a)]),keys:SETKEYS,ph:SETPH,hint:plus?'Сложи коэффициенты: a + b + c.':'Посчитай a − b + c.',
short:plus?`a + b + c = 0 → корни 1 и c/a = ${rat(c,a)}.`:`a − b + c = 0 → корни −1 и −c/a = ${rat(-c,a)}.`,
explain:`${plus?`a + b + c = ${a} ${sgn(b)} ${Math.abs(b)} ${sgn(c)} ${Math.abs(c)} = 0 → x₁ = 1 (подставь x = 1 — получишь a + b + c = 0).`:`a − b + c = ${a} − ${P(b)} ${sgn(c)} ${Math.abs(c)} = 0 → x₁ = −1 (подставь x = −1 — получишь a − b + c = 0).`}<br>Второй корень — из произведения: x₁x₂ = c/a = ${rat(c,a)} → x₂ = <b>${rat(plus?c:-c,a)}</b>.`,
explain2:`Проверим через сумму: ${n(r[0])} + (${rat(plus?c:-c,a)}) = ${rat(plus?a+c:-(a+c),a)}, и по Виета −b/a = ${rat(-b,a)} ✅. Трюк работает для любых a, b, c с a ± b + c = 0 — экономит кучу времени.`};});

/* L3 */
G(3,()=>{const o=mk(`Если m + n = −p и m·n = q, то m и n — корни уравнения ${M('x² + px + q = 0')}`,[`Если m + n = p и m·n = q, то m и n — корни уравнения ${M('x² + px + q = 0')}`,`Если m·n = q, то m и n — корни уравнения ${M('x² + px + q = 0')}`,`Если m + n = −p, то m и n — корни уравнения ${M('x² + px + q = 0')}`]);
return {type:'choice',q:'Как звучит <b>обратная</b> теорема Виета?',...o,short:'Нужны оба условия: сумма −p и произведение q.',
explain:`Обратная теорема: если ${M('m + n = −p')} <b>и</b> ${M('mn = q')}, то m, n — корни ${M('x² + px + q = 0')}.<br>Почему: ${M('(x − m)(x − n) = x² − (m + n)x + mn = x² + px + q')} — значит, при x = m и x = n уравнение обращается в 0.<br>Одного условия мало: 2·3 = 6 и 1·6 = 6, но корни ${M('x² − 5x + 6')} — только 2 и 3.`,
explain2:`Обратная теорема — «прямая наоборот». Прямая: «корни → сумма и произведение». Обратная: «сумма и произведение → корни». Условия те же: сумма = −p, произведение = q.`};},'r');
G(3,()=>{const o=mk(M('x² − (x₁ + x₂)x + x₁x₂ = 0'),[M('x² + (x₁ + x₂)x + x₁x₂ = 0'),M('x² − (x₁ + x₂)x − x₁x₂ = 0'),M('x² + x₁x₂·x + (x₁ + x₂) = 0')]);
return {type:'choice',q:'Приведённое квадратное уравнение с корнями x₁ и x₂ — это…',...o,short:'Минус сумма при x, плюс произведение.',
explain:`${M('(x − x₁)(x − x₂) = x² − (x₁ + x₂)x + x₁x₂')}. Поэтому уравнение: ${M('x² − (x₁ + x₂)x + x₁x₂ = 0')}.<br>При x стоит <b>минус сумма</b> (ведь p = −(x₁ + x₂)), свободный член — произведение.`,
explain2:`Проверь на корнях 1 и 2: правильная формула даёт ${M('x² − 3x + 2 = 0')}. Подставь x = 1: 1 − 3 + 2 = 0 ✅. А «x² + 3x + 2» при x = 1 даёт 6 ✗.`};},'r');
G(3,()=>{let r1,r2;do{r1=nz(-9,9);r2=nz(-9,9);}while(r1===r2||r1+r2===0);const S=r1+r2,T=r1*r2;
const o=mk(M(Q(1,-S,T)+' = 0'),[M(Q(1,S,T)+' = 0'),M(Q(1,-S,-T)+' = 0'),M(Q(1,S,-T)+' = 0')]);
return {type:'choice',q:`Составь приведённое квадратное уравнение с корнями ${n(r1)} и ${n(r2)}.`,...o,short:`Сумма ${n(S)}, произведение ${n(T)} → ${M(Q(1,-S,T)+' = 0')}.`,
explain:`Сумма: ${n(r1)} + ${P(r2)} = ${n(S)}. Произведение: ${n(r1)}·${P(r2)} = ${n(T)}.<br>${M('x² − (x₁ + x₂)x + x₁x₂ = 0')} → x² − (${n(S)})·x + (${n(T)}) = 0 → <b>${M(Q(1,-S,T)+' = 0')}</b>.<br>Частая ошибка — поставить при x саму сумму, а не минус сумму.`,
explain2:`Другой путь: ${M(`(x ${sgn(-r1)} ${Math.abs(r1)})(x ${sgn(-r2)} ${Math.abs(r2)}) = 0`)}. Раскроем: ${M(Q(1,-S,T))}. Проверка: при x = ${n(r1)} получаем ${r1*r1} ${sgn(-S*r1)} ${Math.abs(S*r1)} ${sgn(T)} ${Math.abs(T)} = 0 ✅.`};});
G(3,()=>{let u,v,w;do{v=R(2,5);u=nz(-7,7);w=nz(-5,5);}while(gcd(Math.abs(u),v)!==1||u+v*w===0);
const ok=Q(v,-(u+v*w),u*w)+' = 0';const o=mk(M(ok),[M(Q(v,u+v*w,u*w)+' = 0'),M(Q(v,-(u+w),u*w)+' = 0'),M(Q(v,-(u+v*w),-u*w)+' = 0')]);
return {type:'choice',q:`Составь квадратное уравнение с <b>целыми</b> коэффициентами, корни которого ${rat(u,v)} и ${n(w)}.`,...o,short:`Сумма ${rat(u+v*w,v)}, произведение ${rat(u*w,v)}; умножаем на ${v}.`,
explain:`Сумма: ${rat(u,v)} + ${P(w)} = ${rat(u+v*w,v)}. Произведение: ${rat(u,v)}·${P(w)} = ${rat(u*w,v)}.<br>Приведённое: ${M(`x² ${sgn(-(u+v*w))} ${rat(Math.abs(u+v*w),v)}x ${sgn(u*w)} ${rat(Math.abs(u*w),v)} = 0`)}.<br>Умножаем на ${v}, чтобы убрать дроби: <b>${M(ok)}</b>.`,
explain2:`Через множители: корень ${rat(u,v)} даёт множитель ${M(`(${poly([[v,'x'],[-u,'']])})`)}, корень ${n(w)} — ${M(`(${poly([[1,'x'],[-w,'']])})`)}. Перемножим: ${M(ok.replace(' = 0',''))}. Проверь подстановкой x = ${n(w)}: ${v*w*w} ${sgn(-(u+v*w)*w)} ${Math.abs((u+v*w)*w)} ${sgn(u*w)} ${Math.abs(u*w)} = 0 ✅.`};});
G(3,()=>{let m,k;do{m=nz(-5,5);k=pick([2,3,5,6,7]);}while(m*m===k);
const ok=Q(1,-2*m,m*m-k)+' = 0';const o=mk(M(ok),[M(Q(1,2*m,m*m-k)+' = 0'),M(Q(1,-2*m,m*m+k)+' = 0'),M(Q(1,-m,m*m-k)+' = 0')]);const rt=`${n(m)} ± ${sq(k)}`;
return {type:'choice',q:`Составь приведённое квадратное уравнение с корнями ${M(rt)}.`,...o,short:`Сумма ${2*m}, произведение ${m*m} − ${k} = ${m*m-k}.`,
explain:`x₁ = ${n(m)} + ${sq(k)}, x₂ = ${n(m)} − ${sq(k)}.<br>Сумма: корни ±${sq(k)} сокращаются → ${n(2*m)}.<br>Произведение: ${M(`(${n(m)} + ${sq(k)})(${n(m)} − ${sq(k)}) = ${P(m)}² − (${sq(k)})² = ${m*m} − ${k} = ${m*m-k}`)} (разность квадратов!).<br>Уравнение: <b>${M(ok)}</b>.`,
explain2:`Проверка через формулу корней: у ${M(ok)} D₁ = ${m*m} − ${P(m*m-k)} = ${k}, x = ${n(m)} ± ${sq(k)} ✅. Иррациональные корни всегда ходят парами «± √», поэтому коэффициенты получаются целыми.`};});

/* L4 */
G(4,()=>{const o=mk(M('x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂'),[M('x₁² + x₂² = (x₁ + x₂)² + 2x₁x₂'),M('x₁² + x₂² = (x₁ + x₂)²'),M('x₁² + x₂² = (x₁ + x₂)² − x₁x₂')]);
return {type:'choice',q:'Как выразить x₁² + x₂² через сумму и произведение корней?',...o,short:'Из квадрата суммы вычитаем 2x₁x₂.',
explain:`${M('(x₁ + x₂)² = x₁² + 2x₁x₂ + x₂²')}. Значит, ${M('x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂')}.<br>Ошибка «(x₁ + x₂)²» — это как сказать (a + b)² = a² + b², забыв удвоенное произведение.`,
explain2:`Проверь на числах 1 и 2: x₁² + x₂² = 1 + 4 = 5. Формула: 3² − 2·2 = 5 ✅. А 3² + 4 = 13, 3² = 9, 9 − 2 = 7 ✗.`};},'r');
G(4,()=>{const o=mk(M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr('x₁ + x₂','x₁x₂')}`),[M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr('x₁x₂','x₁ + x₂')}`),M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr(1,'x₁ + x₂')}`),M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr(2,'x₁x₂')}`)]);
return {type:'choice',q:`Допиши формулу для ${M(`${fr(1,'x₁')} + ${fr(1,'x₂')}`)}:`,...o,short:'Общий знаменатель x₁x₂, в числителе x₂ + x₁.',
explain:`Приводим к общему знаменателю: ${M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr('x₂ + x₁','x₁x₂')}`)}. Сумма корней — в числителе, произведение — в знаменателе.`,
explain2:`Числа 2 и 3: 1/2 + 1/3 = 5/6. Формула: (2 + 3)/(2·3) = 5/6 ✅. А 1/(2 + 3) = 1/5 ✗ — дроби так не складываются.`};},'r');
G(4,()=>{const [p,q]=redEq(true);const s=-p,t=q,ans=s*s-2*t;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Не решая его, найди ${M('x₁² + x₂²')}.`,ans,hint:'x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂.',
short:`s = ${n(s)}, t = ${n(t)}: ${P(s)}² − 2·${P(t)} = ${n(ans)}.`,
explain:`D = ${p*p-4*q} > 0 — корни есть. По Виета: ${vs(p,q)}.<br>${M('x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂')} = ${P(s)}² − 2·${P(t)} = ${s*s} ${sgn(-2*t)} ${Math.abs(2*t)} = <b>${n(ans)}</b>.`,
explain2:`Корни здесь некрасивые (x = ${fr(`${n(-p)} ± ${sq(p*p-4*q)}`,2)}), и возводить их в квадрат долго. А через сумму и произведение — две строчки. Это и есть сила теоремы Виета.`};});
G(4,()=>{const [p,q]=redEq(true);const s=-p,t=q;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Найди ${M(`${fr(1,'x₁')} + ${fr(1,'x₂')}`)}.`,ans:s/t,hint:'Приведи к общему знаменателю. Ответ можно записать дробью, например −3/4.',
short:`${fr('x₁ + x₂','x₁x₂')} = ${fr(n(s),n(t))} = ${rat(s,t)}.`,
explain:`D = ${p*p-4*q} > 0. По Виета: ${vs(p,q)}.<br>${M(`${fr(1,'x₁')} + ${fr(1,'x₂')} = ${fr('x₁ + x₂','x₁x₂')}`)} = ${fr(n(s),n(t))} = <b>${rat(s,t)}</b>.`,
explain2:`Представь, что корни — 2 и 3: 1/2 + 1/3 = 3/6 + 2/6 = 5/6 = (2 + 3)/(2·3). То же самое с нашими корнями: сумма ${n(s)} делить на произведение ${n(t)}.`};});
G(4,()=>{const [p,q]=redEq(true);const s=-p,t=q;const num=s*s-2*t;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Найди ${M(`${fr('x₁','x₂')} + ${fr('x₂','x₁')}`)}.`,ans:num/t,hint:'Общий знаменатель x₁x₂, в числителе x₁² + x₂².',
short:`${fr('x₁² + x₂²','x₁x₂')} = ${fr(n(num),n(t))} = ${rat(num,t)}.`,
explain:`По Виета: ${vs(p,q)} (D = ${p*p-4*q} > 0).<br>${M(`${fr('x₁','x₂')} + ${fr('x₂','x₁')} = ${fr('x₁² + x₂²','x₁x₂')}`)}.<br>x₁² + x₂² = ${P(s)}² − 2·${P(t)} = ${n(num)}.<br>Ответ: ${fr(n(num),n(t))} = <b>${rat(num,t)}</b>.`,
explain2:`Это «матрёшка»: сначала нашли x₁² + x₂² (через s² − 2t), потом поделили на x₁x₂ = t. Главное — каждое выражение сводить к s и t.`};});
G(4,()=>{let p,q;do{p=nz(-5,5);q=R(2,12);}while(p*p-4*q>=0||p*p-2*q>=0);const v=p*p-2*q;const none='корней нет — выражение не имеет смысла';
const o=mk(none,[n(v),n(p*p+2*q),n(p*p)]);
return {type:'choice',q:`Чему равно ${M('x₁² + x₂²')}, где x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}?`,...o,hint:'Посчитай по формуле — и подумай, может ли сумма квадратов быть такой.',
short:`D = ${p*p-4*q} < 0 — корней нет.`,
explain:`По формуле получилось бы ${P(-p)}² − 2·${q} = ${n(v)} — <b>отрицательная сумма квадратов</b>! Так не бывает.<br>Причина: D = ${p*p} − ${4*q} = ${p*p-4*q} < 0, корней у уравнения <b>нет</b>, и теорема Виета не применима.`,
explain2:`Квадрат любого числа ≥ 0, сумма квадратов тоже ≥ 0. Если формула выдаёт отрицательное число — это сигнал: ты применил Виета к уравнению без корней. Всегда начинай с проверки D.`};});

/* L5 */
G(5,()=>{const o=mk(M('x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂)'),[M('x₁³ + x₂³ = (x₁ + x₂)³ − x₁x₂(x₁ + x₂)'),M('x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂'),M('x₁³ + x₂³ = (x₁ + x₂)³ + 3x₁x₂(x₁ + x₂)')]);
return {type:'choice',q:'Как выразить x₁³ + x₂³ через сумму и произведение?',...o,short:'s³ − 3ts.',
explain:`${M('(x₁ + x₂)³ = x₁³ + 3x₁²x₂ + 3x₁x₂² + x₂³ = x₁³ + x₂³ + 3x₁x₂(x₁ + x₂)')}.<br>Значит, ${M('x₁³ + x₂³ = s³ − 3ts')}, где s — сумма, t — произведение.`,
explain2:`Проверь на 1 и 2: 1 + 8 = 9. Формула: 3³ − 3·2·3 = 27 − 18 = 9 ✅.`};},'r');
G(5,()=>{const o=mk(M('(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂'),[M('(x₁ − x₂)² = (x₁ + x₂)² − 2x₁x₂'),M('(x₁ − x₂)² = (x₁ + x₂)² + 4x₁x₂'),M('(x₁ − x₂)² = (x₁ + x₂)² − x₁x₂')]);
return {type:'choice',q:'Квадрат разности корней через сумму и произведение:',...o,short:'s² − 4t.',
explain:`${M('(x₁ − x₂)² = x₁² − 2x₁x₂ + x₂² = (x₁² + x₂²) − 2x₁x₂ = (s² − 2t) − 2t = s² − 4t')}.<br>Для приведённого уравнения это в точности D = p² − 4q.`,
explain2:`Числа 2 и 5: (5 − 2)² = 9. Формула: 7² − 4·10 = 49 − 40 = 9 ✅.`};},'r');
G(5,()=>{const [p,q]=redEq(false);const s=-p,t=q,ans=s**3-3*t*s;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Не решая, найди ${M('x₁³ + x₂³')}.`,ans,hint:'x₁³ + x₂³ = s³ − 3ts.',
short:`${P(s)}³ − 3·${P(t)}·${P(s)} = ${n(ans)}.`,
explain:`D = ${p*p-4*q} > 0. ${vs(p,q)}.<br>${M('x₁³ + x₂³ = s³ − 3ts')} = ${P(s)}³ − 3·${P(t)}·${P(s)} = ${n(s**3)} ${sgn(-3*t*s)} ${Math.abs(3*t*s)} = <b>${n(ans)}</b>.`,
explain2:`Другой путь — через сумму кубов: ${M('x₁³ + x₂³ = (x₁ + x₂)(x₁² − x₁x₂ + x₂²)')} = s·(s² − 3t) = ${P(s)}·(${s*s} ${sgn(-3*t)} ${Math.abs(3*t)}) = ${n(ans)}. Совпало.`};});
G(5,()=>{let r1,r2;do{r1=nz(-9,9);r2=nz(-9,9);}while(r1===r2);const p=-(r1+r2),q=r1*r2,d=Math.abs(r1-r2);
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Найди ${M('|x₁ − x₂|')} — расстояние между корнями.`,ans:d,hint:'(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂.',
short:`(x₁ − x₂)² = ${P(-p)}² − 4·${P(q)} = ${d*d}, |x₁ − x₂| = ${d}.`,
explain:`${vs(p,q)}.<br>${M('(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂')} = ${p*p} ${sgn(-4*q)} ${Math.abs(4*q)} = ${d*d}.<br>${M('|x₁ − x₂|')} = √${d*d} = <b>${d}</b>.`,
explain2:`Можно и решить: корни ${n(r1)} и ${n(r2)}, расстояние между ними на числовой прямой ${d}. Заметь: (x₁ − x₂)² — это в точности дискриминант приведённого уравнения, D = ${p*p-4*q}.`};});
G(5,()=>{const [p,q]=redEq(true);const s=-p,t=q;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Найди ${M('x₁²x₂ + x₁x₂²')}.`,ans:s*t,hint:'Вынеси общий множитель x₁x₂.',
short:`x₁x₂(x₁ + x₂) = ${P(t)}·${P(s)} = ${n(s*t)}.`,
explain:`Выносим общий множитель: ${M('x₁²x₂ + x₁x₂² = x₁x₂(x₁ + x₂)')}.<br>По Виета (D = ${p*p-4*q} > 0): ${vs(p,q)}.<br>Ответ: ${P(t)}·${P(s)} = <b>${n(s*t)}</b>.`,
explain2:`Любое «симметричное» выражение (не меняется, если поменять x₁ и x₂ местами) можно выразить через s и t. Тут проще всего — вынести x₁x₂.`};});

/* L6 */
G(6,()=>{const o=mk('корни есть, и они разных знаков',['оба корня отрицательные','корней нет','оба корня положительные']);
return {type:'choice',q:`Что можно сказать о корнях уравнения ${M('x² + px + q = 0')}, если <b>q < 0</b>?`,...o,short:'q < 0 → D > 0 и произведение отрицательно.',
explain:`Если q < 0, то D = p² − 4q = p² + (положительное) > 0 — корни <b>точно есть</b>. Их произведение x₁x₂ = q < 0 → корни <b>разных знаков</b>.`,
explain2:`Произведение двух чисел отрицательно, только если одно положительное, а другое отрицательное. Пример: ${M('x² − x − 6 = 0')} → 3 и −2.`};},'r');
G(6,()=>{const o=mk('оба положительные',['оба отрицательные','разных знаков','один из них равен нулю']);
return {type:'choice',q:`У уравнения ${M('x² + px + q = 0')} D > 0, q > 0 и p < 0. Какие у него корни?`,...o,short:'Произведение > 0 → один знак; сумма −p > 0 → оба положительные.',
explain:`x₁x₂ = q > 0 → корни одного знака (и не нули). x₁ + x₂ = −p > 0 (p отрицательное) → сумма положительна → <b>оба положительные</b>.`,
explain2:`Пример: ${M('x² − 5x + 6 = 0')}: p = −5 < 0, q = 6 > 0 → корни 2 и 3, оба положительные. Условие D > 0 важно: без него корней могло бы не быть вовсе.`};},'r');
G(6,()=>{let p,q;do{p=nz(-12,12);q=nz(-30,30);}while(p*p-4*q<=0);
const opts=['оба положительные','оба отрицательные','разных знаков, больший по модулю — положительный','разных знаков, больший по модулю — отрицательный'];
const right=q>0?(p<0?0:1):(p<0?2:3);const o=mk(opts[right],opts);
return {type:'choice',q:`Не решая уравнение ${M(Q(1,p,q)+' = 0')}, определи знаки его корней.`,...o,hint:'Посмотри на знак произведения q и суммы −p.',
short:`x₁x₂ = ${n(q)}, x₁ + x₂ = ${n(-p)} → ${opts[right]}.`,
explain:`D = ${p*p-4*q} > 0 — корни есть.<br>Произведение x₁x₂ = ${n(q)} ${q>0?'> 0 → одного знака':'< 0 → разных знаков'}.<br>Сумма x₁ + x₂ = ${n(-p)} ${-p>0?'> 0':'< 0'} → ${q>0?(-p>0?'оба положительные':'оба отрицательные'):(-p>0?'положительный корень больше по модулю':'отрицательный корень больше по модулю')}.<br>Ответ: <b>${opts[right]}</b>.`,
explain2:`Корни: x = ${fr(`${n(-p)} ± ${sq(p*p-4*q)}`,2)} ≈ ${n(Math.round((-p+Math.sqrt(p*p-4*q))/2*100)/100)} и ${n(Math.round((-p-Math.sqrt(p*p-4*q))/2*100)/100)}. Видишь — знаки как мы и сказали, а решать было не нужно.`};});
G(6,()=>{let r1,r2;do{r1=R(1,8);r2=R(1,8);}while(r1===r2);const S=r1+r2,T=r1*r2;const m=R(1,4);
const ok=M(Q(1,-S,T)+' = 0');const o=mk(ok,[M(Q(1,S,T)+' = 0'),M(Q(1,-S,-T)+' = 0'),M(Q(1,-m,m*m+R(1,3))+' = 0')]);
return {type:'choice',q:'Какое из уравнений имеет <b>два положительных</b> корня?',...o,hint:'Нужно: D > 0, произведение > 0, сумма > 0.',
short:`${ok}: D > 0, x₁x₂ = ${T} > 0, x₁ + x₂ = ${S} > 0.`,
explain:`Условия: корни есть (D > 0), произведение q > 0, сумма −p > 0.<br>• ${ok}: D = ${S*S-4*T} > 0, q = ${T} > 0, −p = ${S} > 0 ✅ (корни ${Math.min(r1,r2)} и ${Math.max(r1,r2)}).<br>• ${M(Q(1,S,T))}: сумма −${S} < 0 — оба отрицательные.<br>• ${M(Q(1,-S,-T))}: q < 0 — разных знаков.<br>• Уравнение с маленьким p и большим q: D < 0 — корней нет совсем.`,
explain2:`Самая хитрая ловушка — уравнение, где знаки p и q «правильные», но D < 0. Положительность суммы и произведения ничего не значит, если корней нет.`};});

/* L7 */
G(7,()=>{const o=mk(`из суммы ${M('x₂ = −p − x₁')} или произведения ${M('x₂ = q/x₁')}`,[`${M('x₂ = −x₁')} — корни всегда противоположны`,`${M('x₂ = q − x₁')}`,`${M('x₂ = p/x₁')}`]);
return {type:'choice',q:`Известен один корень x₁ уравнения ${M('x² + px + q = 0')}. Как быстрее всего найти второй?`,...o,short:'По Виета: через сумму или произведение.',
explain:`По теореме Виета x₁ + x₂ = −p и x₁x₂ = q. Значит, ${M('x₂ = −p − x₁')} или ${M('x₂ = q / x₁')} (если x₁ ≠ 0). Выбирай ту формулу, где всё известно.`,
explain2:`Пример: ${M('x² − 9x + 20 = 0')}, x₁ = 4. Через сумму: x₂ = 9 − 4 = 5. Через произведение: 20/4 = 5. Совпало.`};},'r');
G(7,()=>{let r1,r2;do{r1=nz(-8,8);r2=nz(-8,8);}while(r1+r2===0||r1===r2);const p=-(r1+r2),q=r1*r2;
return {type:'num',q:`Число ${n(r1)} — корень уравнения ${M(poly([[1,'x²'],[p,'x']])+' + q = 0')}. Найди q.`,ans:q,hint:'Найди второй корень через сумму, потом q — как произведение.',
short:`x₂ = −p − x₁ = ${n(-p)} − ${P(r1)} = ${n(r2)}, q = ${n(r1)}·${P(r2)} = ${n(q)}.`,
explain:`По Виета x₁ + x₂ = −p = ${n(-p)}. Значит, x₂ = ${n(-p)} − ${P(r1)} = ${n(r2)}.<br>q = x₁x₂ = ${n(r1)}·${P(r2)} = <b>${n(q)}</b>.`,
explain2:`Способ подстановкой: x = ${n(r1)} — корень, значит ${P(r1)}² ${sgn(p)} ${Math.abs(p)}·${P(r1)} + q = 0 → ${r1*r1} ${sgn(p*r1)} ${Math.abs(p*r1)} + q = 0 → q = ${n(q)}. Совпало.`};});
G(7,()=>{let r1,r2;do{r1=nz(-6,6);r2=nz(-8,8);}while(r1+r2===0||r1===r2);const p=-(r1+r2),q=r1*r2;
return {type:'num',q:`Число ${n(r1)} — корень уравнения ${M('x² + px '+(q<0?'− ':'+ ')+Math.abs(q)+' = 0')}. Найди p.`,ans:p,hint:'Известно q — найди второй корень через произведение.',
short:`x₂ = q/x₁ = ${n(q)}/${P(r1)} = ${n(r2)}, p = −(x₁ + x₂) = ${n(p)}.`,
explain:`x₁x₂ = q = ${n(q)} → x₂ = ${n(q)} : ${P(r1)} = ${n(r2)}.<br>x₁ + x₂ = −p → p = −(${n(r1)} + ${P(r2)}) = <b>${n(p)}</b>.`,
explain2:`Подстановкой: ${P(r1)}² + p·${P(r1)} ${sgn(q)} ${Math.abs(q)} = 0 → ${r1*r1+q} ${sgn(r1)} ${Math.abs(r1)===1?'':Math.abs(r1)}p = 0 → p = ${n(p)}. Совпало. Итоговое уравнение: ${M(Q(1,p,q)+' = 0')}.`};});
G(7,()=>{let a,r1,u;do{a=R(2,5);r1=nz(-5,5);u=nz(-9,9);}while(gcd(Math.abs(u),a)!==1);const b=-(a*r1+u),c=r1*u;
return {type:'num',q:`Один из корней уравнения ${M(Q(a,b,c)+' = 0')} равен ${n(r1)}. Найди второй корень (дробь можно вводить как 3/4).`,ans:u/a,hint:'x₁x₂ = c/a.',
short:`x₂ = c/(a·x₁) = ${fr(n(c),`${a}·${P(r1)}`)} = ${rat(u,a)}.`,
explain:`По Виета ${M(`x₁x₂ = ${fr('c','a')}`)} = ${fr(n(c),a)}.<br>x₂ = ${fr(n(c),a)} : ${P(r1)} = ${fr(n(c),n(a*r1))} = <b>${rat(u,a)}</b>.`,
explain2:`Через сумму: x₁ + x₂ = −b/a = ${rat(-b,a)} → x₂ = ${rat(-b,a)} − ${P(r1)} = ${rat(-b-a*r1,a)}. Тот же ответ.`};});

/* L8 — ★ */
G(8,()=>{const o=mk('каждый корень — делитель q',['каждый корень — делитель p','оба корня обязательно положительны','q — делитель каждого корня']);
return {type:'choice',q:`p и q — целые, и оба корня уравнения ${M('x² + px + q = 0')} — целые. Что из этого всегда верно?`,...o,short:'x₁x₂ = q → каждый корень делит q.',
explain:`По Виета x₁·x₂ = q. Если x₁, x₂ целые, то q = x₁·(целое) — значит, x₁ делит q; так же x₂ делит q.<br>Это главный инструмент в задачах «найдите все p, при которых корни целые»: перебираем делители q.`,
explain2:`Пример: ${M('x² − 7x + 10 = 0')}: корни 2 и 5 — оба делители 10. А делителями p = −7 они не являются, так что вариант «делитель p» неверен.`};},'r');
G(8,()=>{const N=pick([6,8,10,12,15,18,20,24,28,30,36]);const pairs=[];for(let d=1;d*d<=N;d++)if(N%d===0)pairs.push([d,N/d]);
const ps=new Set();pairs.forEach(([d,e])=>{ps.add(-(d+e));ps.add(d+e);});const cnt=ps.size;
return {type:'num',q:`Сколько существует целых p, при которых оба корня уравнения ${M(`x² + px + ${N} = 0`)} — целые числа?`,ans:cnt,hint:`Корни — пара целых чисел с произведением ${N}. Корни одного знака.`,
short:`Пары делителей: ${pairs.map(([d,e])=>`${d}·${e}`).join(', ')} и такие же с минусами → p = ${[...ps].sort((x,y)=>x-y).map(n).join(', ')}.`,
explain:`По Виета x₁x₂ = ${N}, x₁ + x₂ = −p. Корни целые → это пара делителей ${N}, причём одного знака (произведение > 0).<br>Положительные пары: ${pairs.map(([d,e])=>`(${d}, ${e}) → p = ${-(d+e)}`).join('; ')}.<br>Отрицательные пары дают противоположные p: ${pairs.map(([d,e])=>d+e).join(', ')}.<br>Всего различных p: <b>${cnt}</b>.`,
explain2:`Почему других нет: если корни целые, их произведение ${N} — значит, это пара делителей ${N}. Мы перебрали все такие пары, каждая даёт ровно одно p. Порядок в паре не важен — (2, 3) и (3, 2) дают то же p.`,
_bf:()=>{let c=0;for(let p=-200;p<=200;p++){const D=p*p-4*N;if(D<0)continue;const s=Math.round(Math.sqrt(D));if(s*s===D&&(s-p)%2===0)c++;}return c===cnt||`brute ${c} vs ${cnt}`;}};},'s');
G(8,()=>{const r=R(1,6),d=R(1,4);const q=r*(r+d),p0=2*r+d;
return {type:'set',q:`Найди все p, при которых корни уравнения ${M(`x² + px + ${q} = 0`)} отличаются на ${d}.`,ans:[-p0,p0],keys:SETKEYS,ph:'значения p через запятую',hint:'(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂.',
short:`p² − ${4*q} = ${d*d} → p² = ${p0*p0} → p = ±${p0}.`,
explain:`По Виета: x₁ + x₂ = −p, x₁x₂ = ${q}. Условие: |x₁ − x₂| = ${d}, т. е. (x₁ − x₂)² = ${d*d}.<br>${M('(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂')} = p² − ${4*q}.<br>p² − ${4*q} = ${d*d} → p² = ${p0*p0} → p = <b>±${p0}</b>.<br>Проверка D: D = p² − ${4*q} = ${d*d} > 0 — корни есть. При p = −${p0}: корни ${r} и ${r+d}; при p = ${p0}: −${r} и −${r+d}.`,
explain2:`Заметь: (x₁ − x₂)² для приведённого уравнения — это его дискриминант. «Корни отличаются на ${d}» = «D = ${d*d}». Отсюда сразу p² − ${4*q} = ${d*d}.`,
_bf:()=>{const got=[];for(let p=-60;p<=60;p++){const D=p*p-4*q;if(D<0)continue;if(Math.abs(Math.sqrt(D)-d)<1e-9)got.push(p);}return (got.length===2&&got[0]===-p0&&got[1]===p0)||`brute ${got}`;}};},'s');
G(8,()=>{const [p,q]=redEq(false);const s=-p,t=q;const a2=s*s-2*t,ans=a2*a2-2*t*t;
return {type:'num',q:`x₁, x₂ — корни уравнения ${M(Q(1,p,q)+' = 0')}. Не решая, найди ${M('x₁⁴ + x₂⁴')}.`,ans,hint:'x₁⁴ + x₂⁴ = (x₁² + x₂²)² − 2(x₁x₂)².',
short:`x₁² + x₂² = ${n(a2)}; x₁⁴ + x₂⁴ = ${P(a2)}² − 2·${P(t)}² = ${n(ans)}.`,
explain:`D = ${p*p-4*q} > 0. ${vs(p,q)}.<br>1) x₁² + x₂² = s² − 2t = ${s*s} ${sgn(-2*t)} ${Math.abs(2*t)} = ${n(a2)}.<br>2) ${M('x₁⁴ + x₂⁴ = (x₁² + x₂²)² − 2x₁²x₂²')} = ${P(a2)}² − 2·${P(t)}² = ${a2*a2} − ${2*t*t} = <b>${n(ans)}</b>.`,
explain2:`Это та же формула «квадрат суммы минус удвоенное произведение», только применённая к числам x₁² и x₂²: их сумма ${n(a2)}, произведение ${n(t*t)}.`,
_bf:()=>{const D=Math.sqrt(p*p-4*q),x1=(-p+D)/2,x2=(-p-D)/2;return Math.abs(x1**4+x2**4-ans)<1e-6||'x^4 mismatch';}};},'s');
G(8,()=>{let q,p0;do{q=nz(-6,8);p0=R(1,7);}while(p0*p0-2*q<=0);const S=p0*p0-2*q,D=p0*p0-4*q;const ans=D>=0?[-p0,p0]:[];
return {type:'set',q:`Найди все p, при которых сумма квадратов корней уравнения ${M(`x² + px ${sgn(q)} ${Math.abs(q)} = 0`)} равна ${S}.`,ans,keys:SETKEYS,ph:'значения p через запятую, нет — ∅',hint:'x₁² + x₂² = p² − 2q. И не забудь проверить, что корни существуют!',
short:`p² − ${P(2*q)} = ${S} → p = ±${p0}; D = ${p0*p0} ${sgn(-4*q)} ${Math.abs(4*q)} = ${D} ${D>=0?'≥ 0 — подходит':'< 0 — корней нет, ответ ∅'}.`,
explain:`По Виета: x₁ + x₂ = −p, x₁x₂ = ${n(q)}.<br>x₁² + x₂² = p² − 2·${P(q)} = p² ${sgn(-2*q)} ${Math.abs(2*q)} = ${S} → p² = ${p0*p0} → p = ±${p0}.<br><b>Проверка существования корней:</b> D = p² − 4q = ${p0*p0} ${sgn(-4*q)} ${Math.abs(4*q)} = ${D}.<br>${D>=0?`D ≥ 0 — корни есть. Ответ: <b>p = ±${p0}</b>.`:`D < 0 — при p = ±${p0} корней нет! Значит, «сумма квадратов корней» не существует. Ответ: <b>∅</b>.`}`,
explain2:`${D>=0?'Здесь проверка прошла, но её всё равно надо делать: в похожих задачах «найденные» p часто оказываются фальшивыми.':`Это классическая ловушка олимпиад и ЕГЭ: Виета выдал p = ±${p0}, но при этом p уравнение ${M(Q(1,p0,q))} = 0 не имеет корней. Теорема Виета не работает для несуществующих корней.`}`,
_bf:()=>{const got=[];for(let p=-40;p<=40;p++){const DD=p*p-4*q;if(DD<0)continue;const r=Math.sqrt(DD),x1=(-p+r)/2,x2=(-p-r)/2;if(Math.abs(x1*x1+x2*x2-S)<1e-9)got.push(p);}return JSON.stringify(got)===JSON.stringify(ans)||`brute ${got}`;}};},'s');
G(8,()=>{const k=R(2,4),r=nz(-4,4);const p=-(1+k)*r,q=k*r*r;
return {type:'num',q:`Один из корней уравнения ${M(`${poly([[1,'x²'],[p,'x']])} + q = 0`)} в ${k} раза больше другого. Найди q.`,ans:q,hint:`Обозначь корни x и ${k}x. Запиши сумму по Виета.`,
short:`x + ${k}x = ${n(-p)} → x = ${n(r)}; q = ${n(r)}·${n(k*r)} = ${q}.`,
explain:`Пусть корни t и ${k}t. По Виета: t + ${k}t = −p = ${n(-p)} → ${k+1}t = ${n(-p)} → t = ${n(r)}.<br>Корни: ${n(r)} и ${n(k*r)}. q = x₁x₂ = ${n(r)}·${P(k*r)} = <b>${q}</b>.<br>Проверка: ${M(Q(1,p,q)+' = 0')} → D = ${p*p-4*q} = ${Math.abs((k-1)*r)}², корни ${n(r)} и ${n(k*r)} ✅.`,
explain2:`Можно в общем виде: если корни t и kt, то сумма (1 + k)t, произведение kt². Значит, q = k·(сумма/(1 + k))² = ${k}·(${n(-p)}/${k+1})² = ${k}·${r*r} = ${q}.`,
_bf:()=>{const D=Math.sqrt(p*p-4*q),x1=(-p+D)/2,x2=(-p-D)/2;return (Math.abs(x1-k*x2)<1e-9||Math.abs(x2-k*x1)<1e-9)||'ratio fail';}};},'s');
G(8,()=>{let p,q;do{[p,q]=redEq(false);}while(q===1||q===-1||p*p-2*q===0);const A=p*p-2*q,B=q*q;
const ok=M(poly([[1,'y²'],[-A,'y'],[B,'']])+' = 0');
const o=mk(ok,[M(poly([[1,'y²'],[A,'y'],[B,'']])+' = 0'),M(poly([[1,'y²'],[-(p*p+2*q),'y'],[B,'']])+' = 0'),M(poly([[1,'y²'],[-A,'y'],[q,'']])+' = 0')]);
return {type:'choice',q:`Составь приведённое квадратное уравнение, корни которого — <b>квадраты</b> корней уравнения ${M(Q(1,p,q)+' = 0')}.`,...o,hint:'Новые корни y₁ = x₁², y₂ = x₂². Найди их сумму и произведение через s и t.',
short:`y₁ + y₂ = s² − 2t = ${A}, y₁y₂ = t² = ${B}.`,
explain:`Старое уравнение: D = ${p*p-4*q} > 0, ${vs(p,q)}.<br>Новые корни y₁ = x₁², y₂ = x₂²:<br>• сумма ${M('x₁² + x₂² = s² − 2t')} = ${p*p} ${sgn(-2*q)} ${Math.abs(2*q)} = ${A};<br>• произведение ${M('x₁²x₂² = (x₁x₂)²')} = ${P(q)}² = ${B}.<br>По обратной теореме: ${ok}.`,
explain2:`Ловушки: при y ставится <b>минус</b> сумма; свободный член — (x₁x₂)² = ${B}, а не ${n(q)}. Проверь на простом примере: x² − 3x + 2 = 0 (корни 1 и 2) → квадраты 1 и 4 → y² − 5y + 4 = 0. По формуле: s² − 2t = 9 − 4 = 5, t² = 4 ✅.`,
_bf:()=>{const D=Math.sqrt(p*p-4*q),x1=(-p+D)/2,x2=(-p-D)/2;return (Math.abs(x1*x1+x2*x2-A)<1e-6&&Math.abs(x1*x1*x2*x2-B)<1e-6)||'sq eq fail';}};},'s');

/* ---------- widget ---------- */
function onTheory(root){const el=root.querySelector('#w-vieta');if(!el)return;
  el.innerHTML=`<label>x₁ = <output id="w1">−1</output><input type="range" id="s1" min="-6" max="6" step="0.5" value="-1"></label>
<label>x₂ = <output id="w2">3</output><input type="range" id="s2" min="-6" max="6" step="0.5" value="3"></label>
<div class="fig" id="wpic"></div><div id="wtxt" style="text-align:center"></div>`;
  const g=id=>el.querySelector(id);
  const upd=()=>{const a=+g('#s1').value,b=+g('#s2').value;g('#w1').textContent=n(a);g('#w2').textContent=n(b);const S=a+b,T=a*b;
    g('#wpic').innerHTML=plot(1,-S,T,{roots:a===b?[a]:[a,b]});
    g('#wtxt').innerHTML=`Сумма корней: ${n(a)} + ${P(b)} = <b>${n(S)}</b>, произведение: ${n(a)}·${P(b)} = <b>${n(T)}</b><br>Уравнение: ${M(Q(1,-S,T)+' = 0')}${a===b?'<br>Корни совпали — D = 0, парабола касается оси.':''}`;};
  ['#s1','#s2'].forEach(id=>g(id).addEventListener('input',upd));upd();}

window.TOPIC={id:'a8_vieta',title:'Теорема Виета',subtitle:'Алгебра · 8 класс',
intro:`<p>Теорема Виета — суперсила: корни в уме, уравнение по корням за секунду, хитрые выражения от корней без решения. Здесь от самой теоремы до олимпиадных задач про целые корни. В разделе про обратную теорему — живой график: задаёшь корни, получаешь уравнение.</p>`,
theory,symbols,figs:{},onTheory,
levels:['Теорема Виета для приведённого уравнения','Виет для любого квадратного уравнения','Корни в уме: подбор','Обратная теорема: уравнение по корням','x₁² + x₂², 1/x₁ + 1/x₂ и другие','Кубы, разность корней','Знаки корней без решения','Один корень известен','★ Олимпиадные задачи'],
gens};
})();
